SELECT c.course_id FROM ai_messages m
JOIN ai_conversations c ON c.conversation_id = m.conversation_id AND c.user_id = m.user_id
WHERE m.user_id = #{userId} AND m.message_id = #{messageId}

SELECT topic_id, toc_key_state, toc_key_hash, toc_key_line, source_textbook_key FROM course_topics
WHERE user_id = #{userId} AND course_id = #{courseId} AND topic_id IN
#{id}

SELECT section_id FROM material_sections
WHERE user_id = #{userId} AND material_id = #{materialId}
ORDER BY section_id LIMIT 1
